code:
def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Considers only (), [], {} and ignores other characters.
    """
    opening = set('([{')
    closing_map = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing_map:
            if not stack or stack[-1] != closing_map[ch]:
                return False
            stack.pop()
    return not stack

