def solve(grid):
    """Count islands in a possibly non‑rectangular grid.
    grid: list of rows, each row is a list of 0/1 ints. Cells connect up, down, left, right.
    Returns the number of distinct islands. Handles empty grid and rows with zero length.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Determine max columns to bound neighbors; but we will check per row length dynamically.
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # bounds check for current row length
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            # explore four directions
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

