def solve(grid):
    """Count islands in a possibly irregular grid.
    Treat any cell whose value evaluates to a land cell (1, True, '1', etc.) as 1.
    Connectivity is 4-directional.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(v):
        # Accept common representations of land
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            return v == 1
        if isinstance(v, str):
            return v.strip() == '1'
        return False
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if not is_land(grid[i][j]):
                continue
            visited.add((i, j))
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if is_land(val) and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

