def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports operators +, -, *, /. Operands may be strings or numbers.
    Division truncates toward zero.
    Returns 0 for empty input or malformed expression.
    """
    if not tokens:
        return 0
    ops = {'+', '-', '*', '/'}
    stack = []
    for token in tokens:
        # Ensure token is a string for operator check
        tok = str(token).strip()
        if tok in ops:
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Handle division by zero gracefully
                if b == 0:
                    return 0
                res = int(a / b)  # truncates toward zero
            stack.append(res)
        else:
            try:
                stack.append(int(tok))
            except ValueError:
                # ignore non‑numeric tokens
                continue
    return stack[-1] if stack else 0

