def solve(grid):
    """Count islands in a possibly non‑rectangular grid.
    grid is a list of lists containing 0/1. Cells are 4‑connected.
    Returns 0 for empty grid or empty rows.
    """
    if not grid:
        return 0
    n = len(grid)
    # Determine max columns for bounds checking
    max_cols = max((len(row) for row in grid), default=0)
    visited = [ [False]*len(row) for row in grid ]
    def neighbors(i, j):
        # four directions, check bounds for each row's length
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        for di, dj in dirs:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def bfs(start_i, start_j):
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for ni, nj in neighbors(i, j):
                if not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                bfs(i, j)
                islands += 1
    return islands

